// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    address deployer;

    function setUp() public {
        // test runner deploys this test contract; we want to deploy C from here so this test contract is the admin
        c = new C();
        deployer = address(this);
    }

    // General rule (encoded as the single assert): for any caller `actor` and any candidate owner `newOwner`,
    // if actor is not the admin (deployer of C), then calling setOwner by that actor must NOT change c.owner().
    // The mutant removing the onlyAdmin require allows non-admins to change owner, so the mutant will fail this.
    function testFuzz_property(address actor, address newOwner) public {
        // Keep fuzzed addresses broad but avoid the zero-address for clearer semantics (owner can be zero but still allowed)
        // We allow actor to be any address; if actor == address(this) (the admin) then changing owner is allowed
        // and both reference and mutant behave same; we only assert the universal property for ALL inputs by
        // checking that if actor != admin then owner remains unchanged after the call.

        // Record original owner
        address before = c.owner();

        bool ok;
        // Simulate actor calling setOwner. If actor has no code, a simple vm.prank is sufficient.
        vm.prank(actor);
        try c.setOwner(newOwner) returns (bool success) {
            ok = success;
        } catch {
            ok = false;
        }

        // After the call, read owner
        address after = c.owner();

        // If the caller was the admin (this contract), then setOwner may validly change owner.
        // For all other callers, reference contract's onlyAdmin should prevent change, so owner must remain equal to before.
        if (actor != address(this)) {
            assertTrue(after == before);
        } else {
            // If actor is admin, the call may succeed and change owner or may set same owner; both are allowed.
            assertTrue(true);
        }
    }
}

