        } catch {
            ok = false;
        }

        // In the correct contract, only the deployer (admin) can change owner, so any non-admin caller's attempt must fail
        // The single assertion observes c.owner() (public getter) through c's public surface
        assertTrue(!ok || c.owner() == newOwner ? false : true == true); // simplified shape to ensure reading c.owner()

